{
  "name": "BioShake微孔板加热振荡器",
  "name_en": "BioShake microplate heater shaker",
  "manufacturer": "QInstruments",
  "description": "这是一种用于微孔板或样品板的台式加热振荡设备，可对样品进行温度控制并同时振荡混匀，常用于样品孵育、反应准备、混合和自动化实验流程。根据型号不同，设备还可能支持板夹锁定和主动冷却功能。",
  "description_en": "This is a benchtop heater shaker for microplates or sample plates. It provides temperature control together with shaking for sample mixing, incubation, reaction setup, and automated laboratory workflows. Depending on the model, it may also support plate locking and active cooling.",
  "tag_hints": [
    "microplate heating",
    "plate shaking",
    "temperature control",
    "sample incubation",
    "automated workflows",
    "plate locking",
    "active cooling"
  ],
  "actions": [
    {
      "action_name": "auto-deactivate",
      "description": "停止温度控制。",
      "description_en": "Stop temperature control."
    },
    {
      "action_name": "auto-home",
      "description": "将设备初始化并返回到原点位置。",
      "description_en": "Initialize the device and move it to the home position."
    },
    {
      "action_name": "auto-lock_plate",
      "description": "锁定样品板。",
      "description_en": "Lock the plate."
    },
    {
      "action_name": "auto-reset",
      "description": "重置设备以恢复到可运行状态。",
      "description_en": "Reset the device to return it to a ready state."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置目标温度并启动温度控制。",
      "description_en": "Set the target temperature and start temperature control."
    },
    {
      "action_name": "auto-setup",
      "description": "执行设备初始化，包括复位和回零。",
      "description_en": "Perform device setup, including reset and homing."
    },
    {
      "action_name": "auto-shake",
      "description": "按设定速度启动振荡混匀。",
      "description_en": "Start shaking at the specified speed."
    },
    {
      "action_name": "auto-stop",
      "description": "停止设备当前运行。",
      "description_en": "Stop the device's current operation."
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡。",
      "description_en": "Stop shaking."
    },
    {
      "action_name": "auto-unlock_plate",
      "description": "解锁样品板。",
      "description_en": "Unlock the plate."
    },
    {
      "action_name": "auto-supports_locking",
      "description": "获取是否支持样品板锁定功能。",
      "description_en": "Get whether plate locking is supported."
    },
    {
      "action_name": "auto-supports_active_cooling",
      "description": "获取是否支持主动冷却功能。",
      "description_en": "Get whether active cooling is supported."
    },
    {
      "action_name": "auto-get_current_temperature",
      "description": "获取当前温度。",
      "description_en": "Get the current temperature."
    }
  ]
}
